import * as E from './engine.mjs';
import {renderBuilding,drawAvatar,drawShop,sceneHit,CANVAS_W,CANVAS_H} from './pixel.mjs';
const $=q=>document.querySelector(q),H=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('ko-KR'),stars=n=>'★'.repeat(n)+'☆'.repeat(5-n),weekday=d=>new Date(d+'T12:00:00Z').getUTCDay(),dl=d=>d.slice(5).replace('-','.');
const KEY='saebom-company-v1',DKEY=KEY+'-sample',days=['일','월','화','수','목','금','토'];
let mode=localStorage.getItem(KEY+'-mode')==='demo'?'demo':'real',view='home',reportTab='body',metric='weight',range='month',shopFloor=2,shopSlot=0,shopTab='buy',filter='all',manageState='placed',zoom=1,selectedDay=null,receiptDate=null,frame=0,animationEpoch=performance.now(),pending=null,toastTimer;
function validate(x){
 if(!x||x.version!==1||!Number.isFinite(x.gold)||!Number.isInteger(x.seed)||!/^\d{4}-\d{2}-\d{2}$/.test(x.day))throw Error('지원하지 않는 백업 파일이에요.');
 for(const k of ['staff','inventory','ledger','transactions','contracts','claimed'])if(!Array.isArray(x[k]))throw Error('백업 구조를 확인해주세요.');
 if(!x.records||Array.isArray(x.records)||!x.activities||typeof x.activities!=='object')throw Error('기록을 확인해주세요.');
 if(x.profile){for(const k of ['start','target','height','age'])if(!Number.isFinite(x.profile[k]))throw Error('프로필을 확인해주세요.');if(typeof x.profile.name!=='string'||!['lose','maintain'].includes(x.profile.mode)||!/^\d{2}:\d{2}$/.test(x.profile.closeTime))throw Error('회사 설정을 확인해주세요.');}
 if(x.staff.length>9||x.staff.some(e=>![2,3,4].includes(e.floor)||!Number.isInteger(e.star)||e.star<1||e.star>5||!Array.isArray(e.stats)||e.stats.length!==4||e.stats.some(v=>!Number.isFinite(v))||!Number.isFinite(e.morale)||!Number.isFinite(e.strain)||typeof e.name!=='string'))throw Error('직원 데이터를 확인해주세요.');
 for(const [d,r]of Object.entries(x.records))if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!r||!Number.isFinite(r.weight)||r.weight<=0||r.weight>350||['muscle','fat','sleep','calories'].some(k=>r[k]!=null&&(!Number.isFinite(r[k])||r[k]<0)))throw Error('신체 기록을 확인해주세요.');
 for(const i of x.inventory)if(!E.SHOP.some(a=>a.id===i.id)||i.floor!==null&&![1,2,3,4,5,6].includes(i.floor)||!Number.isFinite(i.paid)||i.level!=null&&(!Number.isInteger(i.level)||i.level<1||i.level>5)||i.skin!=null&&(!Number.isInteger(i.skin)||i.skin<1||i.skin>(i.level||1)))throw Error('비품 데이터를 확인해주세요.');
 for(const l of x.ledger)if(!/^\d{4}-\d{2}-\d{2}$/.test(l.date)||!l.roll||!Number.isFinite(l.roll.factor)||!Number.isFinite(l.dividend)||!Array.isArray(l.events))throw Error('정산 데이터를 확인해주세요.');
 if(x.customQuests!=null&&(!Array.isArray(x.customQuests)||x.customQuests.some(q=>typeof q.id!=='string'||typeof q.title!=='string'||!['daily','weekly'].includes(q.type)||!E.DIFFICULTIES[q.difficulty]||!E.CATEGORIES[q.category]||!Array.isArray(q.days)||!/^\d{4}-\d{2}-\d{2}$/.test(q.startDate))))throw Error('일정 데이터를 확인해주세요.');
 if(x.questLog!=null&&(typeof x.questLog!=='object'||Array.isArray(x.questLog)||Object.values(x.questLog).some(l=>!Number.isFinite(l.amount)||l.amount<0||!Number.isInteger(l.dice)||l.dice<1||l.dice>6)))throw Error('보상 데이터를 확인해주세요.');
 return E.migrateState(x);
}
function load(key){try{const raw=localStorage.getItem(key);if(!raw)return null;try{return validate(JSON.parse(raw))}catch{localStorage.setItem(key+'-recovery',raw);return null}}catch{return null}}
let s=load(mode==='demo'?DKEY:KEY)||(mode==='demo'?E.makeDemo():E.createState());
function save(){try{localStorage.setItem(KEY+'-mode',mode);localStorage.setItem(mode==='demo'?DKEY:KEY,JSON.stringify(s,(key,value)=>key==='__candidates'?undefined:value))}catch{toast('저장 공간이 부족해요. 설정에서 백업해주세요.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function modal(title,html){const same=$('#sheet').open&&$('#sheetTitle').textContent===title,top=$('#sheet').scrollTop;$('#sheetTitle').textContent=title;$('#sheetBody').innerHTML=html;if(!$('#sheet').open)$('#sheet').showModal();$('#sheet').scrollTop=same?top:0;decorate()}
function close(){$('#sheet').close();pending=null}
function confirmAction(title,text,fn){pending=fn;modal(title,`<p class="modal-desc">${H(text)}</p><div class="grid2"><button class="secondary" data-action="close">취소</button><button class="primary" data-action="confirm">확인</button></div>`)}
function ready(){if(s.profile)return true;setup();return false}
function name(){const n=s.profile?.name||'새봄';return /주식회사|컴퍼니|회사$/.test(n)?n:n+' 주식회사'}
function go(v){close();view=v;selectedDay=null;render();$('#screen').scrollTop=0}
const icons={home:'<path d="M4 21V5l8-3 8 3v16M2 21h20M8 7h1m6 0h1M8 11h1m6 0h1M8 15h1m6 0h1M10 21v-3h4v3"/>',diary:'<rect x="4" y="4" width="17" height="17" rx="3"/><path d="M8 2v4m9-4v4M4 9h17m-13 4 2 2 4-4m1 6h3"/>',staff:'<circle cx="10" cy="8" r="4"/><path d="M3 21v-3a7 7 0 0 1 14 0v3m1-17a4 4 0 0 1 0 8m3 9v-3a6 6 0 0 0-3-5"/>',shop:'<path d="m3 10 2-7h14l2 7M4 10v11h16V10M3 10c0 4 6 4 6 0 0 4 6 4 6 0 0 4 6 4 6 0M9 21v-7h6v7"/>',reports:'<path d="M5 2h10l4 4v16H5zM14 2v5h5M8 17l3-4 3 2 3-5M8 9h2"/>'};
function render(){
 cancelAnimationFrame(frame);$('#brandName').textContent=name();$('#accountBar').innerHTML=`<div><small>회사 가치</small><strong>${fmt(E.valuation(s))} V</strong></div><div><small>함께하는 동료</small><strong>${s.staff.length} <span style="font-size:10px;color:#796855">/ 9</span></strong></div><div><small>보유 골드</small><strong class="${s.gold<0?'negative':'gold'}">${fmt(s.gold)} G</strong></div>`;
 document.querySelectorAll('.test-panel [data-action="testAdvance"]').forEach(b=>{b.disabled=mode!=='demo';b.title=mode!=='demo'?'샘플 회사에서만 사용해요.':''});$('#modeLabel').textContent=mode==='demo'?'샘플 회사':'내 회사 · 로컬 저장';$('#testDate').textContent=s.day+' · '+days[weekday(s.day)]+'요일';
 $('#navigation').innerHTML=[['home','회사'],['diary','일정'],['staff','직원'],['shop','가구'],['reports','보고서']].map(([v,label])=>`<button class="nav-item ${v===view?'active':''}" data-action="nav" data-view="${v}" ${v===view?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[v]}</svg>${label}</button>`).join('');
 $('#screen').innerHTML=(!s.profile&&view==='home'?welcome():({home:homePage,diary:diaryPage,staff:staffPage,shop:shopPage,reports:reportsPage}[view]||homePage)());decorate();
 if(view==='home'&&s.profile){const canvas=$('#building');if(!canvas)return;s.__candidates=E.candidates(s);const motion=matchMedia('(prefers-reduced-motion: reduce)').matches;const loop=t=>{if(canvas.isConnected){renderBuilding(canvas,s,motion?30:(t-animationEpoch)/1000);frame=requestAnimationFrame(loop)}};frame=requestAnimationFrame(loop);canvas.addEventListener('click',ev=>{const r=canvas.getBoundingClientRect(),hit=sceneHit((ev.clientX-r.left)*CANVAS_W/r.width,(ev.clientY-r.top)*CANVAS_H/r.height);if(hit){if(hit.action==='candidate')candidateDetail(hit.id);if(hit.action==='meeting')meeting();if(hit.action==='lounge')lounge();if(hit.action==='staff')employeeDetail(hit.id);if(hit.action==='boss')floorDetail(5)}})}
}
function decorate(){document.querySelectorAll('canvas[data-shop]').forEach(c=>drawShop(c,c.dataset.shop,Number(c.dataset.level)||1,Number(c.dataset.skin)||Number(c.dataset.level)||1));document.querySelectorAll('canvas[data-employee]').forEach(c=>{const e=s.staff.find(e=>e.id===c.dataset.employee)||E.candidates(s).find(e=>e.id===c.dataset.employee);if(e)drawAvatar(c,e)})}
function pageTop(k,title,desc,extra=''){return `<div class="page-top"><div><span class="eyebrow blue">${k}</span><h2>${title}</h2><p>${desc}</p></div>${extra}</div>`}
function welcome(){return `<div class="welcome"><div class="welcome-art">☁<br><span style="font-size:12px;letter-spacing:4px;color:#8f6a43">SAEBOM COMPANY</span></div><span class="eyebrow blue">나의 몸, 나의 회사</span><h2>기록이 쌓이면,<br>나의 회사도 자라요.</h2><p>체중을 기록하고 작은 약속을 지켜요.<br>창가의 동료들, 내 취향의 사무실.<br>서두르지 않는 나만의 다이어트 다이어리.</p><button class="primary full" data-action="setup">나의 작은 회사 시작하기 →</button><button class="text-button full" style="text-align:center;margin-top:10px" data-action="demo">먼저 샘플 회사 둘러보기</button></div>`}
function homePage(){const r=s.records[s.day],last=E.latestRecord(s),cs=E.candidates(s);return `<div class="office-head"><span class="eyebrow">${s.day.replaceAll('-','.')} &nbsp; ${mode==='demo'?'COZY CAFE · DEMO':'MY SLOW LITTLE COMPANY'}</span><div class="row" style="margin-top:7px"><div><h2>오늘도, 포근한 출근.</h2><p class="subtle">한 잔의 여유처럼, 나만의 속도로.</p></div><button class="weight-pill" data-action="record"><small>${r?'오늘의 체중':'오늘의 기록 +'}</small><b>${(r?.weight??last?.[1].weight??s.profile.start).toFixed(1)} <span style="font-size:10px">kg</span></b></button></div></div><div class="office-toolbar"><div class="gap"><button class="text-button" data-action="roof" style="padding:0">옥상 휴게실 ↑</button><button class="text-button" data-action="lobby" style="padding:0">1층 방문실 ↓</button></div><div class="zoom-controls"><button data-action="zoomOut" aria-label="건물 축소">−</button><span>${Math.round(zoom*100)}%</span><button data-action="zoomIn" aria-label="건물 확대">+</button></div></div><div class="building-viewport"><div class="building-wrap" style="width:${zoom*100}%"><canvas id="building" role="img" aria-label="포근한 카페 사무실. 직원과 1층에 앉은 면접자를 직접 누르세요. 오른쪽 엘리베이터로 옥상 휴게실에 이동합니다."></canvas>${cs.map((c,i)=>`<button class="scene-hotspot" data-action="candidate" data-id="${H(c.id)}" aria-label="면접자 ${H(c.name)} 면접 보기" style="left:${(45+i*55)/480*100}%;top:83.5%;width:8.75%;height:6.5%"></button>`).join('')}<button class="scene-hotspot" data-action="meeting" aria-label="미팅룸 한보고의 일정 제안서" style="left:59.4%;top:83.8%;width:9.6%;height:6.2%"></button></div></div><div class="office-bottom"><div class="office-message"><span class="message-icon">☕</span><div><b>${s.staff.length?'작은 회사의 속마음이 들리는 곳.':'첫 동료가 면접실에서 기다리고 있어요.'}</b><p>직원은 직접 눌러 확인해요. 면접은 1층 의자에 앉은 지원자를 눌러 시작하세요.</p><button class="text-button" style="padding:6px 0 0" data-action="nav" data-view="diary">오늘의 작은 약속 확인하기 →</button></div></div></div>`}

function questRow(q,date){const log=q.log,done=!!log?.completed,base=E.DIFFICULTIES[q.difficulty][q.type],editable=date===s.day;return `<div class="quest-row ${done?'completed':''}"><button class="quest-check ${done?'done':''}" data-action="toggleQuest" data-id="${H(q.id)}" ${editable?'':'disabled'} aria-label="${H(q.title)} ${done?'완료 취소':'완료'}" aria-pressed="${done}">✓</button><button class="quest-content" data-action="editQuest" data-id="${H(q.id)}"><b>${H(q.title)}</b><span class="meta"><span class="tag ${q.difficulty}">${E.DIFFICULTIES[q.difficulty].label}</span>${q.repeat==='once'?'한 번만':q.type==='weekly'?'매주 반복':q.days.length===7?'매일 반복':q.days.map(i=>days[i]).join('·')+' 반복'} <span style="margin-left:auto">···</span></span></button><span class="quest-reward">${done?'+'+fmt(log.amount):fmt(base)} G<small>${done?'주사위 '+log.dice+' · +'+log.dice*10+'%':'+ 주사위 보너스'}</small></span></div>`}
function diaryPage(){const d=selectedDay||s.day,ws=E.weekStart(d),daily=E.scheduledQuests(s,'daily',d),weekly=E.scheduledQuests(s,'weekly',d),all=[...daily,...weekly],done=all.filter(q=>q.log?.completed).length;return `<div class="screen-inner">${pageTop('MY LITTLE PROMISES','오늘의 작은 약속','할 수 있는 만큼, 나만의 리듬으로.',`<span class="pill">${dl(d)} ${days[weekday(d)]}요일</span>`)}<div class="week-strip">${Array.from({length:7},(_,i)=>{const a=E.addDays(ws,i);return `<button class="day-chip ${a===d?'selected':''}" data-action="selectDay" data-date="${a}" ${a>s.day?'disabled':''}><span>${days[weekday(a)]}</span><b>${Number(a.slice(8))}</b><i></i></button>`}).join('')}</div><div class="quest-summary"><span class="summary-number">${done}<span style="font-size:13px;color:#876c4f"> / ${all.length}</span></span><div><b>${all.length&&done===all.length?'오늘의 약속을 모두 지켰어요!':'작은 한 걸음도 나의 성과예요.'}</b><p>완료한 약속은 한 번 더 눌러 취소할 수 있어요.</p></div></div><div class="section-title"><h3>일일 퀘스트 <span class="tag">${daily.length}</span></h3><button class="plus" data-action="addQuest" data-type="daily" aria-label="일일 퀘스트 추가">+</button></div>${daily.map(q=>questRow(q,d)).join('')||'<div class="empty">비어 있는 오늘, 어떤 약속을 담을까요?<br>+ 버튼으로 직접 추가해보세요.</div>'}<div class="section-title"><h3>주간 퀘스트 <span class="tag">${weekly.length}</span></h3><button class="plus" data-action="addQuest" data-type="weekly" aria-label="주간 퀘스트 추가">+</button></div>${weekly.map(q=>questRow(q,d)).join('')||'<div class="empty">이번 주 나를 위한 약속을 추가해보세요.</div>'}<p class="tip">제목을 누르면 수정·삭제할 수 있어요. 주사위는 1~6, 기본 보상의 10~60%를 더해줘요. ${d!==s.day?'지난 일정은 읽기 전용이에요.':''}</p><button class="secondary full" data-action="today">오늘로 돌아오기</button></div>`}
function staffCard(e){return `<button class="staff-card" data-action="employee" data-id="${H(e.id)}"><div class="avatar-wrap"><canvas class="avatar" data-employee="${H(e.id)}"></canvas></div><div class="staff-info"><div class="row"><b>${H(e.name)} <span class="tag blue">${H(e.keyword)}</span></b><span class="stars">${stars(e.star)}</span></div><p>근속 ${e.tenure}일 · 일급 ${E.WAGES[e.star]} G · ${e.strain>=3?'앞날을 고민 중':'오늘도 함께하는 중'}</p><div class="morale-bar"><i style="width:${e.morale}%"></i></div></div></button>`}
function staffPage(){return `<div class="screen-inner">${pageTop('OUR PEOPLE','함께 자라는 동료','내 안의 의지들이 일하는 작은 회사.','')}${[4,3,2].map(f=>`<div class="section-title"><h3>${f}F ${E.FLOORS[f]}</h3><span class="subtle">${s.staff.filter(e=>e.floor===f).length} / 3</span></div>${s.staff.filter(e=>e.floor===f).map(staffCard).join('')||'<div class="card empty">아직 조용한 부서예요.<br>첫 동료를 기다리고 있어요.</div>'}`).join('')}<div class="notice">직급은 근속에 따라, 능력은 작은 실천에 따라 자라요.<br>좋은 습관도 꾸준히 돌봐주세요. 성장 성향은 함께 지내며 알아가요.</div></div>`}
function location(i){if(!i.equipped||i.floor==null)return '보관 중 · 배치 대기';const a=E.SHOP.find(a=>a.id===i.id);return (i.floor===6?'옥상 휴게실':i.floor+'F '+E.FLOORS[i.floor])+(a.personal&&[2,3,4].includes(i.floor)?' · '+(i.slot+1)+'번 자리':'');}
function effect(a,l=1,i=null){const scope=i&&i.equipped?E.furnitureScope(i):a.scope;return E.SCOPE_LABELS[scope]+' · '+[a.efficiency?'업무 효율 +'+Math.round(a.efficiency*l*1000)/10+'%':'',a.morale?'사기 +'+a.morale*l:''].filter(Boolean).join(' · ')}
const furnitureCategories=[['all','전체'],['computer','컴퓨터'],['desk','책상'],['chair','의자'],['keyboard','키보드'],['deskplant','책상 화분'],['mug','머그'],['clock','시계'],['wallpaper','벽지'],['plant','화분'],['bookshelf','서가'],['board','메모 보드'],['poster','포스터'],['lamp','조명'],['aquarium','수족관'],['rug','러그'],['sofa','소파'],['coffee','커피바'],['water','정수기'],['beanbag','빈백'],['parasol','파라솔'],['teatable','티 테이블'],['flowerbox','꽃상자'],['hammock','해먹'],['speaker','스피커']];
function shopPage(){const list=E.SHOP.filter(a=>filter==='all'||a.kind===filter),owned=s.inventory.filter(i=>(filter==='all'||E.SHOP.find(a=>a.id===i.id).kind===filter)&&(manageState==='placed'?i.equipped:!i.equipped));return `<div class="screen-inner">${pageTop('COZY FURNITURE STUDIO','나의 가구 공방','원목의 온기와 부드러운 패브릭으로 채워요.')}<div class="segmented furniture-tabs"><button data-action="shopTab" data-tab="buy" class="${shopTab==='buy'?'active':''}">구매</button><button data-action="shopTab" data-tab="manage" class="${shopTab==='manage'?'active':''}">관리 <span class="count">${s.inventory.length}</span></button></div><div class="filter-strip furniture-categories">${furnitureCategories.map(([k,n])=>`<button data-action="filter" data-filter="${k}" class="${filter===k?'active':''}">${n}</button>`).join('')}</div>${shopTab==='buy'?`<div class="catalog-note">가구를 먼저 구매하고, <b>배치</b>에서 설치할 공간과 자리를 골라요.</div><div class="shop-grid">${list.map(a=>`<article class="shop-card"><span class="level-tag">Lv.1 → 5</span><div class="shop-sprite"><canvas data-shop="${a.id}"></canvas></div><h4>${a.name}</h4><p>${effect(a)}<br>${a.allowedFloors.length===1?'옥상 전용':a.personal?'직원 자리 · 대표실':a.allowedFloors.includes(6)?'실내 · 옥상 배치 가능':'실내 전용'}</p><div class="row"><b>${fmt(a.price)} G</b><button class="primary small" data-action="buy" data-id="${a.id}" ${s.gold<a.price?'disabled':''}>구매</button></div></article>`).join('')}</div>`:`<div class="segmented"><button class="${manageState==='placed'?'active':''}" data-action="manageState" data-state="placed">배치한 가구 ${s.inventory.filter(i=>i.equipped).length}</button><button class="${manageState==='stored'?'active':''}" data-action="manageState" data-state="stored">보관한 가구 ${s.inventory.filter(i=>!i.equipped).length}</button></div><div class="inventory-list">${owned.map(i=>{const a=E.SHOP.find(a=>a.id===i.id);return `<article class="manage-card"><button class="inventory-card" data-action="furniture" data-id="${i.uid}"><canvas data-shop="${i.id}" data-level="${i.level}" data-skin="${i.skin}"></canvas><div><b>${a.name} <span class="tag">Lv.${i.level}</span></b><small>${location(i)}</small><small>${effect(a,i.level,i)}</small></div><span class="chevron">›</span></button><div class="manage-actions"><button class="secondary small" data-action="place" data-id="${i.uid}">${i.equipped?'배치 변경':'배치'}</button><button class="primary small" data-action="upgrade" data-id="${i.uid}" ${i.level>=5||s.gold<E.upgradeCost(i)?'disabled':''}>${i.level>=5?'최고 레벨':'Lv.'+(i.level+1)+' 업그레이드 · '+fmt(E.upgradeCost(i))+' G'}</button></div></article>`}).join('')||'<div class="empty">이 카테고리의 '+(manageState==='placed'?'배치한':'보관한')+' 가구가 없어요.</div>'}</div>`}<div class="notice" style="margin-top:18px">업무 효율은 해당 직원의 성과 발생 확률에 반영돼요.<br>자리 가구 최대 +18%, 층 가구 +12%, 전체 가구 +8%. 합산 최대 +35%예요. 옥상의 공용 가구 효과는 모든 직원에게 적용돼요.</div></div>`}

function chart(data,kind){
 if(!data.length)return '<div class="empty">측정한 날의 기록을 남기면<br>나의 변화가 이곳에 쌓여요.</div>';
 const vals=data.map(a=>a.value),pad=Math.max(kind==='value'?200:.3,(Math.max(...vals)-Math.min(...vals))*.2),min=Math.min(...vals)-pad,max=Math.max(...vals)+pad,start=data[0].date,end=data.at(-1).date,span=Math.max(1,E.daysBetween(start,end));
 const x=d=>35+E.daysBetween(start,d)/span*281,y=v=>130-(v-min)/(max-min)*104,points=data.map(a=>`${x(a.date)},${y(a.value)}`).join(' '),id='gradient-'+kind;
 return `<svg class="chart" viewBox="0 0 330 164" role="img" aria-label="${kind==='value'?'회사 가치':kind==='weight'?'체중':kind==='muscle'?'골격근량':'체지방량'} 변화 그래프 ${data.length}개 측정"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b58a57" stop-opacity=".28"/><stop offset="1" stop-color="#b58a57" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(k=>{const v=min+(max-min)*k,yy=y(v);return `<line x1="35" x2="316" y1="${yy}" y2="${yy}"/><text x="28" y="${yy+3}" text-anchor="end">${kind==='value'?(v/1000).toFixed(1)+'k':v.toFixed(1)}</text>`}).join('')}${kind==='weight'&&s.profile.target>=min&&s.profile.target<=max?`<path d="M35 ${y(s.profile.target)}H316" stroke="#a99478" stroke-dasharray="5 5"/><text x="315" y="${y(s.profile.target)-5}" text-anchor="end">목표 ${s.profile.target} kg</text>`:''}<polygon points="${x(start)},135 ${points} ${x(end)},135" fill="url(#${id})"/>${data.length>1?`<polyline points="${points}" fill="none" stroke="#98734d" stroke-width="2.5" stroke-linejoin="round"/>`:''}${data.length<50?data.map(a=>`<circle cx="${x(a.date)}" cy="${y(a.value)}" r="3" fill="#fff" stroke="#98734d" stroke-width="1.6"><title>${a.date}: ${a.value}</title></circle>`).join(''):''}<text x="35" y="155">${dl(start)}</text><text x="316" y="155" text-anchor="end">${dl(end)}</text></svg>`
}
function bodyReport(){const start=range==='all'?'0000-01-01':E.addDays(s.day,-({week:6,month:29,year:364}[range])),rows=Object.entries(s.records).filter(([d])=>d>=start&&d<=s.day).sort((a,b)=>a[0].localeCompare(b[0])),data=rows.filter(([,r])=>r[metric]!=null).map(([date,r])=>({date,value:r[metric]})),values=s.ledger.filter(l=>l.date>=start&&l.date<=s.day).map(l=>({date:l.date,value:l.value}));if(!values.some(a=>a.date===s.day))values.push({date:s.day,value:E.valuation(s)});const labels={weight:'체중',muscle:'골격근량',fat:'체지방량'},last=data.at(-1),diff=data.length>1?last.value-data[0].value:null,p=s.profile,latest=E.latestRecord(s);return `<div class="segmented">${[['weight','체중'],['muscle','골격근량'],['fat','체지방량']].map(([k,n])=>`<button class="${metric===k?'active':''}" data-action="metric" data-metric="${k}">${n}</button>`).join('')}</div><div class="filter-strip">${[['week','주간'],['month','월별'],['year','1년'],['all','전체']].map(([k,n])=>`<button data-action="range" data-range="${k}" class="${range===k?'active':''}">${n}</button>`).join('')}<span style="font-size:9px;color:#796855;align-self:center;margin-left:auto">최근 ${range==='all'?'전체 기간':range==='year'?'365일':range==='month'?'30일':'7일'}</span></div><div class="chart-card"><div class="chart-heading"><div><h3>나의 ${labels[metric]} 기록</h3><strong>${last?last.value.toFixed(1):'—'}<small>kg</small></strong><p>${last?last.date+' 측정':'측정한 날에만 남겨도 괜찮아요.'}</p></div><span class="pill" style="max-width:58%;white-space:normal;font-size:9px">${diff==null?'첫 기록부터 차근차근':(diff>0?'+':'')+diff.toFixed(1)+' kg · 기간 변화'}</span></div>${chart(data,metric)}${p&&metric==='weight'?`<div class="mini-total">목표 ${p.target.toFixed(1)} kg · ${p.goalDate||'나의 속도로'}<span style="float:right">${p.mode==='maintain'?'유지 경영':'감량 경영'}</span></div>`:''}</div><div class="chart-card"><div class="chart-heading"><div><h3>우리 회사의 가치</h3><strong>${fmt(E.valuation(s))}<small>V</small></strong><p>체중의 변화와 하루의 시장 흐름이 반영돼요.</p></div><span class="tag blue">매일 배당</span></div>${chart(values,'value')}</div><div class="row"><h3 style="font-size:13px">날짜별 기록</h3><button class="secondary small" data-action="record">기록 추가 +</button></div><div class="record-list">${[...rows].reverse().slice(0,60).map(([d,r])=>`<button data-action="record" data-date="${d}"><span>${d}<small style="display:block;font-size:9px;color:#796855;margin-top:4px">${r.muscle!=null?'골격근 '+r.muscle+' kg ':''}${r.fat!=null?' · 체지방 '+r.fat+' kg':''}</small></span><strong>${r.weight.toFixed(1)} kg &nbsp; ›</strong></button>`).join('')||'<div class="empty">체중 하나부터 기록해보세요.</div>'}</div><p class="tip">골격근량·체지방량은 kg 단위의 선택 기록이에요. 빈 날은 0으로 처리하지 않으며, 점과 점은 측정 흐름을 보여줘요.</p>`}
function receipt(){const d=receiptDate||s.day,l=s.ledger.find(l=>l.date===d),q=E.receiptQuests(s,d),done=q.filter(q=>q.completed),r=s.records[d],wisdom=E.dailyWisdom(s,d),all=q.length>0&&done.length===q.length,any=done.length>0||!!r;const tx=s.transactions.filter(t=>t.date===d),net=tx.reduce((a,t)=>a+t.amount,0);return `<label>돌아볼 날짜<input type="date" id="receiptDate" value="${d}" max="${s.day}" min="${s.created}"></label><article class="receipt"><div class="receipt-head"><span class="eyebrow">A DAY IN MY COMPANY</span><h3>하루의 영수증</h3><p>${H(name())}</p><p>${d} · ${days[weekday(d)]}요일 · ${l?'정산 완료':'오늘의 기록 진행 중'}</p></div><div class="receipt-section"><div class="receipt-label">01 / MY BODY</div><div class="receipt-line"><span>체중 기록</span><strong>${r?r.weight.toFixed(1)+' kg':'아직 기록하지 않았어요'}</strong></div>${[['muscle','골격근량','kg'],['fat','체지방량','kg'],['sleep','수면','시간'],['calories','섭취 칼로리','kcal']].filter(([k])=>r?.[k]!=null).map(([k,n,u])=>`<div class="receipt-line"><span>${n}</span><span>${r[k]} ${u}</span></div>`).join('')}${r?.note?`<p class="field-note">“${H(r.note)}”</p>`:''}</div><div class="receipt-section"><div class="receipt-label">02 / LITTLE PROMISES &nbsp; ${done.length} / ${q.length}</div>${q.map(a=>`<div class="receipt-line"><span class="${a.completed?'yes':'no'}">${a.completed?'✓':'○'} ${H(a.title)}${a.type==='weekly'?'<br><small>이번 주의 약속</small>':''}</span><span class="${a.completed?'yes':'no'}">${a.completed?'완료':'미완료'}</span></div>`).join('')||'<p class="field-note">이 날짜에는 등록된 일정 내역이 없어요.</p>'}</div><div class="receipt-section receipt-money"><div class="receipt-label">03 / COMPANY SETTLEMENT</div>${l?`<div class="receipt-line"><span>선 지급 배당</span><span>+${fmt(l.dividend)} G</span></div><div class="receipt-line"><span>직원 월급</span><span>−${fmt(l.wages)} G</span></div><div class="receipt-line"><span>업무 성과</span><span>+${fmt(l.performance)} G</span></div><div class="receipt-line"><span>시장 흐름</span><span>${l.roll.label}</span></div>`:'<p class="field-note">하루 마감 시간에 배당과 월급이 정산돼요.</p>'}<div class="receipt-line"><span>일정 보상 · 취소 합계</span><span>${fmt(tx.filter(t=>t.label.startsWith('일정 완료:')||t.label.startsWith('완료 취소:')).reduce((a,t)=>a+t.amount,0))} G</span></div><div class="receipt-line receipt-total"><span>하루 골드 변동</span><span>${net>0?'+':''}${fmt(net)} G</span></div></div><div class="daily-wisdom"><span class="eyebrow">오늘의 한 문장</span><p>“${H(wisdom.text)}”</p><button class="text-button" data-action="wisdomLibrary">새봄의 작은 명언집 ↗</button></div><p class="receipt-comment">${all?'나와 한 약속을 모두 지킨 하루.<br>오늘의 꾸준함을 오래 기억해요.':any?'하나라도 남겼다면 충분한 시작이에요.<br>남은 약속은 내일의 나와 이어가요.':'오늘은 잠깐 쉬어간 하루.<br>다음 한 걸음은 언제든 시작할 수 있어요.'}</p><button class="stamp ${s.stamps[d]?'stamped':'pending'} ${!all?'warm':''}" data-action="stamp" data-date="${d}" aria-label="하루 영수증 도장 찍기"><small>SAEBOM COMPANY</small>${all?'참 잘했어요':any?'한 걸음 해냈어요':'내일 또 만나요'}<small>${s.stamps[d]?'기록했어요 ✓':'눌러서 도장 찍기'}</small></button></article>${l?.events.length?`<div class="card"><h3>사무실의 소식</h3>${l.events.map(a=>`<div class="event-line">${H(a)}</div>`).join('')}</div>`:''}`}
function reportsPage(){return `<div class="screen-inner">${pageTop('MY DAYS, MY GROWTH','쌓여가는 나의 기록','숫자와 하루 사이, 나의 변화를 돌아봐요.',`<button class="secondary small" data-action="record">체중 +</button>`)}<div class="segmented report-tabs">${[['body','몸의 변화'],['receipt','하루 영수증'],['money','회계 장부']].map(([k,n])=>`<button class="${reportTab===k?'active':''}" data-action="reportTab" data-tab="${k}">${n}</button>`).join('')}</div>${reportTab==='body'?bodyReport():reportTab==='receipt'?receipt():`<div class="balance-hero"><small>우리 회사의 운영자금</small><h3>${fmt(s.gold)} G</h3><small>가치가 내려가도 보유 골드는 사라지지 않아요.</small></div><div class="card">${s.transactions.slice(0,80).map(t=>`<div class="money-line"><div>${H(t.label)}<small>${t.date}</small></div><strong class="${t.amount>=0?'positive':'negative'}">${t.amount>0?'+':''}${fmt(t.amount)} G</strong></div>`).join('')||'<div class="empty">첫 거래를 기다리고 있어요.</div>'}</div>`}</div>`}
function recordForm(date=s.day,startup=false){if(!ready())return;const r=s.records[date]||{};modal(startup?'대표님, 오늘의 기록부터 시작할까요?':'내 몸의 기록',`${startup?'<span class="startup-label">TODAY’S FIRST LITTLE STEP</span><h3 class="modal-title">오늘의 나를<br>한 줄 남겨주세요.</h3><p class="modal-desc">몸무게 하나면 충분해요.<br>지금 건너뛰어도 다음 출근 때 다시 알려드릴게요.</p>':''}<form id="recordForm"><label>기록 날짜<input name="date" type="date" value="${date}" max="${s.day}" required></label><label>체중 (kg) · 필수<input name="weight" type="number" step=".1" min=".1" max="350" inputmode="decimal" placeholder="오늘의 체중" value="${r.weight??''}" required ${startup?'autofocus':''}></label><div class="form-row"><label>골격근량 (kg)<input name="muscle" type="number" step=".1" min="0" inputmode="decimal" placeholder="선택" value="${r.muscle??''}"></label><label>체지방량 (kg)<input name="fat" type="number" step=".1" min="0" inputmode="decimal" placeholder="선택" value="${r.fat??''}"></label></div><div class="form-row"><label>수면 (시간)<input name="sleep" type="number" step=".1" min="0" max="24" placeholder="선택" value="${r.sleep??''}"></label><label>섭취 칼로리 (kcal)<input name="calories" type="number" min="0" max="20000" placeholder="하루 합계 · 선택" value="${r.calories??''}"></label></div><label>오늘의 한 줄<textarea name="note" maxlength="500" placeholder="오늘의 기분, 남기고 싶은 작은 일.">${H(r.note||'')}</textarea></label><p class="field-note">지난 기록을 수정하면 배당 차액을 정산해요. 이미 사용한 골드는 마이너스가 될 수 있어요.</p><button class="primary full" type="submit">오늘의 기록 저장하기</button></form>`)}
function setup(){const p=s.profile||{};modal(p.name?'회사와 목표 설정':'나의 회사 설립하기',`<form id="profileForm"><div class="onboarding-progress"><i></i><i></i><i></i></div><h3 class="modal-title">대표님의 속도로<br>시작하는 작은 회사.</h3><label>회사 이름<input name="name" value="${H(p.name||'새봄')}" maxlength="24" required></label><div class="form-row"><label>나이<input name="age" type="number" min="18" max="100" value="${p.age||''}" placeholder="성인 기준" required></label><label>키 (cm)<input name="height" type="number" min="100" max="250" step=".1" value="${p.height||''}" required></label></div><div class="form-row"><label>시작 체중 (kg)<input name="start" type="number" step=".1" min=".1" max="350" value="${p.start||''}" required></label><label>목표 체중 (kg)<input name="target" type="number" step=".1" min=".1" max="350" value="${p.target||''}" required></label></div><label>경영 방향<select name="mode"><option value="lose" ${p.mode==='lose'?'selected':''}>감량 · 목표까지 차근차근</option><option value="maintain" ${p.mode==='maintain'?'selected':''}>유지 · 나의 범위를 편안하게</option></select></label><div class="form-row"><label>목표 날짜<input name="goalDate" type="date" value="${p.goalDate||E.addDays(s.day,90)}" required></label><label>유지 허용 범위 ± kg<input name="range" type="number" min=".1" max="10" step=".1" value="${p.range||1}" required></label></div><label>하루 마감 시간 · 한국 시간<input name="closeTime" type="time" value="${p.closeTime||'23:00'}" required></label><p class="field-note">배당이 먼저 지급되고 월급이 정산돼요. 일요일 마감은 한 주의 마지막 보고서예요.</p><button class="primary full" type="submit">${s.profile?'설정 저장하기':'회사 설립하기 →'}</button></form>`)}
function rename(){if(!ready())return;modal('회사 이름 바꾸기',`<form id="renameForm"><p class="modal-desc">대표님이 좋아하는 이름으로 불러주세요.</p><label>회사 이름<input name="name" maxlength="24" value="${H(s.profile.name)}" required autofocus></label><button class="primary full" type="submit">이름 저장하기</button></form>`)}
function questEditor(id=null,type='daily'){if(!ready())return;const q=s.customQuests.find(q=>q.id===id)||{type,title:'',difficulty:'easy',category:'habit',repeat:type==='weekly'?'weekly':'weekdays',days:[0,1,2,3,4,5,6],startDate:s.day};modal((q.type==='weekly'?'주간':'일일')+' 퀘스트 '+(id?'수정':'추가'),`<form id="questForm" data-id="${id||''}" data-type="${q.type}"><label>제목<input name="title" value="${H(q.title)}" maxlength="80" placeholder="예: 퇴근 후 가볍게 산책하기" required autofocus></label><div class="form-row"><label>난이도<select name="difficulty" id="questDifficulty">${Object.entries(E.DIFFICULTIES).map(([k,v])=>`<option value="${k}" ${q.difficulty===k?'selected':''}>${v.label}</option>`).join('')}</select></label><label>분류<select name="category">${Object.entries(E.CATEGORIES).map(([k,v])=>`<option value="${k}" ${q.category===k?'selected':''}>${v}</option>`).join('')}</select></label></div><label>${q.type==='weekly'?'시작 주':'시작 날짜'}<input type="date" name="startDate" value="${q.startDate}" required></label><label>반복<select name="repeat" id="questRepeat">${q.type==='daily'?`<option value="weekdays" ${q.repeat!=='once'?'selected':''}>요일을 골라 반복</option><option value="once" ${q.repeat==='once'?'selected':''}>한 번만</option>`:`<option value="weekly" ${q.repeat!=='once'?'selected':''}>매주 반복</option><option value="once" ${q.repeat==='once'?'selected':''}>이번 주 한 번만</option>`}</select></label>${q.type==='daily'?`<div id="weekdayBlock" class="${q.repeat==='once'?'hide':''}"><span class="field-note">반복할 요일</span><div class="weekday-picker">${[1,2,3,4,5,6,0].map(n=>`<label><input name="days" type="checkbox" value="${n}" ${q.days.includes(n)?'checked':''}><span>${days[n]}</span></label>`).join('')}</div></div>`:''}<div id="rewardPreview" class="reward-preview">${rewardPreview(q.type,q.difficulty)}</div><p class="field-note">이미 받은 보상은 수정해도 바뀌지 않아요. 삭제하면 앞으로의 목록에서 숨겨지고, 완료 내역은 영수증에 남아요.</p><button class="primary full" type="submit">일정 저장하기</button>${id?`<button type="button" class="text-button full" style="color:#a26a59;text-align:center;margin-top:8px" data-action="deleteQuest" data-id="${H(id)}">이 일정 삭제하기</button>`:''}</form>`)}
function rewardPreview(type,difficulty){const base=E.DIFFICULTIES[difficulty][type];return `기본 보상 <b>${base} G</b> + 주사위 추가 보상 <b>10~60%</b><br>완료하면 총 ${Math.round(base*1.1)}~${Math.round(base*1.6)} G를 받아요.`}
function diceModal(log){const rotations={1:[0,0],2:[0,-90],3:[-90,0],4:[90,0],5:[0,90],6:[0,180]},[rx,ry]=rotations[log.dice],pips={1:[5],2:[1,9],3:[1,5,9],4:[1,3,7,9],5:[1,3,5,7,9],6:[1,3,4,6,7,9]};modal('작은 약속, 기분 좋은 보너스',`<div class="dice-scene"><div class="cube" style="--rx:${rx}deg;--ry:${ry}deg" aria-label="주사위 ${log.dice}">${[1,2,3,4,5,6].map(n=>`<div class="dice-face">${pips[n].map(p=>`<i style="grid-column:${(p-1)%3+1};grid-row:${Math.floor((p-1)/3)+1}"></i>`).join('')}</div>`).join('')}</div>${Array.from({length:12},(_,i)=>`<i class="dice-confetti" style="--r:${i*30}deg;--c:${['#c09a69','#b6ab87','#d8aa90','#d5bc81'][i%4]}"></i>`).join('')}</div><div class="dice-result"><p>${H(log.title)}</p><h3>+${fmt(log.amount)} G</h3><span class="pill">주사위 ${log.dice} · ${log.dice*10}% 추가 보상</span><p>기본 ${log.base} G + 보너스 ${log.amount-log.base} G<br>오늘의 한 걸음이 회사에 쌓였어요.</p><button class="primary full" data-action="close">기분 좋게 계속하기</button></div>`)}
function furniture(uid){const i=s.inventory.find(i=>i.uid===uid);if(!i)return;const a=E.SHOP.find(a=>a.id===i.id);modal(a.name+' 관리',`<div class="shop-sprite" style="height:145px"><canvas data-shop="${i.id}" data-level="${i.level}" data-skin="${i.skin}" style="width:210px;height:144px"></canvas></div><div class="row"><h3 style="margin:0">${a.name}</h3><span class="pill">Lv.${i.level} / 5</span></div><p class="field-note">${location(i)}<br>${effect(a,i.level,i)}</p><button class="primary full" data-action="place" data-id="${uid}">${i.equipped?'다른 공간에 배치하기':'구매한 가구 배치하기'}</button>${i.equipped?`<button class="text-button full" style="text-align:center" data-action="store" data-id="${uid}">보관실로 옮기기</button>`:''}<div class="divider"></div>${i.level<5?`<button class="secondary full" data-action="upgrade" data-id="${uid}" ${s.gold<E.upgradeCost(i)?'disabled':''}>Lv.${i.level+1} 업그레이드 · ${fmt(E.upgradeCost(i))} G</button><p class="tip">다음 효과: ${effect(a,i.level+1,i)}</p>`:'<div class="mini-total">최고 레벨이에요. 해금한 스킨을 자유롭게 골라주세요.</div>'}<div class="section-title"><h3>스킨 컬렉션</h3><span class="tag">효과는 현재 레벨 유지</span></div><div class="skin-grid">${a.skins.map((skin,n)=>`<button class="skin-card ${i.skin===n+1?'active':''}" data-action="skin" data-id="${uid}" data-skin="${n+1}" ${n+1>i.level?'disabled':''}><canvas data-shop="${a.id}" data-level="${n+1}"></canvas><b>${skin}</b><span>${n+1>i.level?'Lv.'+(n+1)+'에서 해금':i.skin===n+1?'선택한 모습':'Lv.'+(n+1)+' 스킨'}</span></button>`).join('')}</div>`)}
function placement(uid,floor=null){const i=s.inventory.find(i=>i.uid===uid);if(!i)return;const a=E.SHOP.find(a=>a.id===i.id),allowed=E.allowedFloors(i.id);modal(a.name+' · 배치',`<div class="placement-summary"><canvas data-shop="${i.id}" data-level="${i.level}" data-skin="${i.skin}"></canvas><div><b>어디에 둘까요?</b><p>${a.personal?'설치할 층과 직원 자리를 선택하세요.':'설치 가능한 공간만 보여드려요.'}</p></div></div><div class="placement-floors">${allowed.map(f=>`<button class="place-floor ${floor===f?'selected':''}" data-action="placementFloor" data-id="${uid}" data-floor="${f}"><b>${f===6?'ROOF':f+'F'}</b><span>${E.FLOORS[f]}</span><small>${a.personal&&[2,3,4].includes(f)?'자리 선택 →':f===6?'전체 직원 효과':'공간 공용'}</small></button>`).join('')}</div>${floor!=null?`<div class="section-title"><h3>${floor===6?'옥상':floor+'층'} · ${a.personal&&[2,3,4].includes(floor)?'자리 선택':'배치 확인'}</h3></div>${(a.personal&&[2,3,4].includes(floor)?[0,1,2]:[0]).map(seat=>{const employee=s.staff.find(e=>e.floor===floor&&e.seat===seat),old=s.inventory.find(o=>o.uid!==uid&&o.equipped&&o.floor===floor&&(o.slot||0)===seat&&E.SHOP.find(a=>a.id===o.id).kind===a.kind);return `<button class="placement-seat" data-action="placeConfirm" data-id="${uid}" data-floor="${floor}" data-slot="${seat}"><div><b>${a.personal&&[2,3,4].includes(floor)?(seat+1)+'번 자리 · '+H(employee?.name||'빈 자리'):'이 공간에 배치'}</b><small>${old?E.SHOP.find(a=>a.id===old.id).name+' → 기존 가구는 보관실로 이동':'바로 배치할 수 있어요'}</small></div><span>배치 →</span></button>`}).join('')}`:''}<p class="tip">구매할 때만 골드가 사용돼요. 배치 변경과 보관은 무료예요.</p>`)}
function wisdomLibrary(){const max=Math.min(14,E.daysBetween(s.created,s.day)+1);modal('새봄의 작은 명언집',`<p class="modal-desc">열심히 한 날도, 쉬어간 날도.<br>나의 생활에 맞춰 남기는 새봄의 하루 문장이에요.</p>${Array.from({length:max},(_,i)=>{const d=E.addDays(s.day,-i),w=E.dailyWisdom(s,d);return `<div class="wisdom-entry"><span>${d}</span><p>“${H(w.text)}”</p></div>`}).join('')}`)}

function employeeDetail(id){const e=s.staff.find(e=>e.id===id);if(!e)return;modal(e.name+' · '+e.keyword,`<div class="candidate-detail"><div class="avatar-wrap"><canvas class="avatar" data-employee="${H(id)}"></canvas></div><h3>${H(e.name)} <span class="tag blue">${H(e.keyword)}</span></h3><div class="stars">${stars(e.star)}</div><p>${e.floor}F ${E.FLOORS[e.floor]} · 근속 ${e.tenure}일</p></div><div class="equipment-breakdown"><b>현재 업무 효율 +${Math.round(E.efficiencyBonus(s,e.floor,e.seat)*1000)/10}%</b><p>자리 +${Math.round(E.efficiencyBreakdown(s,e.floor,e.seat).seat*1000)/10}% · 층 +${Math.round(E.efficiencyBreakdown(s,e.floor,e.seat).floor*1000)/10}% · 전체 +${Math.round(E.efficiencyBreakdown(s,e.floor,e.seat).company*1000)/10}%</p></div><div class="stat-grid">${E.STATS.map((n,i)=>`<div>${n}<strong>${fmt(e.stats[i])}</strong></div>`).join('')}</div><div class="row subtle"><span>직원 사기</span><b>${Math.round(e.morale)} / 100</b></div><div class="morale-bar"><i style="width:${e.morale}%"></i></div><div class="divider"></div><div class="row subtle"><span>일급 / 퇴직금</span><b>${E.WAGES[e.star]} G / ${E.WAGES[e.star]*3} G</b></div><p class="field-note">직원들의 일상 대화는 옥상 휴게실에서 들을 수 있어요.</p><label>부서 재배치<select id="moveFloor">${[2,3,4].map(f=>`<option value="${f}" ${e.floor===f?'selected':''}>${f}F ${E.FLOORS[f]}</option>`).join('')}</select></label><div class="grid2"><button class="secondary" data-action="move" data-id="${id}">재배치</button><button class="danger" data-action="fire" data-id="${id}">퇴직금 지급 · 해고</button></div>`)}
function candidateDetail(id){const c=E.candidates(s).find(c=>c.id===id);if(!c)return;modal('1층 면접실 · 지원자 면접',`<div class="candidate-detail"><div class="avatar-wrap"><canvas class="avatar" data-employee="${H(c.id)}"></canvas></div><span class="eyebrow blue">NEW COLLEAGUE</span><h3>${H(c.name)}</h3><span class="tag blue">${H(c.keyword)}</span><div class="stars" style="margin-top:12px">${stars(c.star)}</div><p>새로운 의지를 우리 회사에 초대해보세요.</p></div><div class="divider"></div><div class="row subtle"><span>채용 준비금 / 일급</span><b>${c.fee} G / ${c.wage} G</b></div><label style="margin-top:20px">근무할 부서<select id="hireFloor">${[2,3,4].map(f=>`<option value="${f}" ${f===c.floor?'selected':''}>${f}F ${E.FLOORS[f]} · ${s.staff.filter(e=>e.floor===f).length}/3</option>`).join('')}</select></label><button class="primary full" data-action="hire" data-id="${H(c.id)}" ${s.staff.length>=9||s.gold<c.fee?'disabled':''}>우리 회사로 채용하기</button>`)}
const suggestions=[{title:'햇살을 보며 산책하기',difficulty:'easy',category:'exercise',type:'daily'},{title:'잠들기 전 잠깐 스트레칭',difficulty:'easy',category:'rest',type:'daily'},{title:'물 한 잔 마시고 쉬어가기',difficulty:'easy',category:'habit',type:'daily'},{title:'이번 주 운동 세 번 해보기',difficulty:'normal',category:'exercise',type:'weekly'},{title:'영화 한 편으로 나를 충전하기',difficulty:'easy',category:'rest',type:'weekly'}];
function meeting(){if(!ready())return;modal('1층 미팅룸 · 오늘의 제안서',`<span class="eyebrow blue">A SMALL PROPOSAL FOR YOU</span><h3 class="modal-title">대표님을 위한<br>작은 일정 제안이에요.</h3><p class="modal-desc">마음에 드는 보고서를 일정에 담아보세요.<br>완료는 일정에서, 보상은 주사위와 함께 받아요.</p>${suggestions.map((q,i)=>`<div class="contract-card"><div class="row"><span class="tag blue">${q.type==='weekly'?'주간':'일일'} 보고서</span><span class="tag ${q.difficulty}">${E.DIFFICULTIES[q.difficulty].label}</span></div><h3>${q.title}</h3><div class="row"><span class="subtle">${E.DIFFICULTIES[q.difficulty][q.type]} G + 주사위 보너스</span><button class="secondary small" data-action="addSuggestion" data-index="${i}">내 일정에 담기 +</button></div></div>`).join('')}<button class="secondary full" data-action="investors">투자사 계약 보고서 보기 →</button>`)}
function lounge(){modal('옥상 · 휴게실',`<span class="eyebrow blue">TAKE A LITTLE BREAK</span><h3 class="modal-title">같이 쉬면,<br>이야기가 시작돼요.</h3><p class="modal-desc">직원들이 업무 중 잠깐 엘리베이터를 타고 옥상으로 올라와요.<br>두 명 이상 모이면 직원 머리 위에 대화가 떠요.<br>회사 분위기와 직원들의 마음을 들어보세요.</p><div class="notice">소파·커피바·빈백·파라솔로 옥상 카페를 꾸며보세요. 라운지 가구의 사기 효과는 모든 직원에게 적용돼요.</div><button class="primary full" style="margin-top:17px" data-action="decorateFloor" data-floor="6">옥상 가구 관리 →</button>`)}
function investors(){modal('미팅룸 · 투자사 계약',`${E.INVESTORS.map(o=>{const done=s.claimed.includes('contract:'+s.day+':'+o.id);return `<div class="contract-card"><div class="row"><span class="tag ${o.id==='temptation'?'hard':'blue'}">${o.tag}</span><b style="color:#9a702f;font-size:11px">+${o.reward} G</b></div><h3>${o.name} · ${o.title}</h3><p>${o.desc}</p><div class="row"><span class="subtle">${o.cost}</span><button class="secondary small" data-action="invest" data-id="${o.id}" ${done?'disabled':''}>${done?'계약 완료':'검토 후 수락'}</button></div></div>`}).join('')}<p class="field-note">생활 퀘스트와 별도의 게임 계약이에요. 필요한 활동은 수락할 때 확인할 수 있어요.</p>`)}
function floorDetail(f){if(f!==5)return;modal('대표이사실',`<h3 class="modal-title">모든 결정은<br>대표님으로부터.</h3><p class="modal-desc">목표 ${s.profile.target} kg · ${s.profile.mode==='maintain'?'유지 경영':'감량 경영'}</p><button class="primary full" data-action="setup">회사와 목표 설정</button>`)}
function settings(){modal('회사 설정',`<p class="modal-desc">${mode==='demo'?'샘플 회사의 가상 기록을 확인 중이에요.':'기록은 현재 브라우저에 자동 저장돼요.'}</p><button class="secondary full" data-action="setup">회사와 목표 · 마감 시간 설정</button><div class="backup-actions"><button class="secondary" data-action="export">백업 내려받기</button><button class="secondary" data-action="import">백업 가져오기</button></div>${localStorage.getItem((mode==='demo'?DKEY:KEY)+'-recovery')?'<button class="secondary full" data-action="recoverBackup">이전 데이터 원본 내려받기</button><p class="field-note">불러오지 못한 데이터 원본을 별도로 보관했어요.</p>':''}<input id="importFile" type="file" accept="application/json,.json" hidden><div class="divider"></div>${mode==='demo'?'<button class="primary full" data-action="testAdvance">검사용 · 하루 진행 →</button><p class="field-note">현재 날짜를 마감하고 다음 날로 넘어가요. 실제 달력과 다른 가상 날짜가 될 수 있어요.</p>':''}<div class="grid2"><button class="secondary" data-action="demo">샘플 회사</button><button class="secondary" data-action="real">내 회사</button></div>${mode==='demo'?'<button class="text-button full" style="text-align:center;margin-top:9px" data-action="resetDemo">샘플 새로 만들기</button>':''}<div class="divider"></div><div class="notice">일정 보상: 일일 30 / 60 / 100 G, 주간 100 / 200 / 350 G. 주사위로 10~60%를 더해줘요.<br>가구는 5레벨까지 성장해요. 회사 이름은 상단 이름을 눌러 바꿀 수 있어요.<br>무료 로컬 검사용 버전 · 자동 건강 데이터 연결 없음.</div>`)}
function settled(report){if(!report)return;receiptDate=report.date;modal('하루 결산 · '+report.date,`<div class="roulette"><span class="eyebrow blue">TODAY’S MARKET</span><h3>${report.roll.label}</h3><p class="subtle">회사 가치 ${fmt(report.value)} V</p><h3 style="font-size:27px">+${fmt(report.dividend)} G</h3><p class="subtle">배당 먼저 지급 · 월급 −${fmt(report.wages)} G<br>직원 성과 +${fmt(report.performance)} G</p></div>${weekday(report.date)===0?'<p class="field-note">한 주를 마쳤어요. 월요일부터 새로운 주간 약속이 시작돼요.</p>':''}<p class="field-note">${report.events.slice(0,4).map(H).join('<br>')||'조용하게 기록이 쌓인 하루였어요.'}</p><button class="primary full" data-action="openReceipt">하루 영수증 확인하기 →</button>`)}
function switchMode(next,reset=false){save();mode=next;s=reset?E.makeDemo():load(next==='demo'?DKEY:KEY)||(next==='demo'?E.makeDemo():E.createState());if(next==='real')E.catchUp(s);selectedDay=null;receiptDate=null;animationEpoch=performance.now();view='home';save();close();render();startup()}
function startup(){if(s.profile&&!Number.isFinite(s.records[s.day]?.weight))recordForm(s.day,true)}
function exportJson(data,filename){if(window.SaebomAndroid?.saveBackup){window.SaebomAndroid.saveBackup(data,filename);toast('백업 파일을 저장할 위치를 선택해주세요.');return}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업 파일을 내려받았어요.')}
function download(){exportJson(JSON.stringify({...s,__candidates:undefined},null,2),'새봄-'+mode+'-'+s.day+'.json')}
function mutate(fn){try{const result=fn();save();render();return result}catch(e){toast(e.message);return null}}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{
 if(a==='nav'){if(ready())go(b.dataset.view)}
 else if(a==='close')close();else if(a==='setup')setup();else if(a==='settings')settings();else if(a==='rename')rename();else if(a==='record')recordForm(b.dataset.date||s.day);
 else if(a==='demo')switchMode('demo');else if(a==='real')switchMode('real');else if(a==='resetDemo')confirmAction('샘플 회사 새로 만들기','샘플 기록만 새로 만들어요. 내 회사 기록은 그대로 남아요.',()=>switchMode('demo',true));
 else if(a==='recoverBackup'){const raw=localStorage.getItem((mode==='demo'?DKEY:KEY)+'-recovery');if(raw)exportJson(raw,'새봄-복구원본.json');}
 else if(a==='confirm'){const fn=pending;pending=null;close();fn?.()}
 else if(a==='zoomIn'||a==='zoomOut'){zoom=Math.min(1.7,Math.max(.7,Math.round((zoom+(a==='zoomIn'?.15:-.15))*100)/100));render()}
 else if(a==='selectDay'){selectedDay=b.dataset.date;render()}else if(a==='today'){selectedDay=null;render()}
 else if(a==='addQuest')questEditor(null,b.dataset.type);else if(a==='editQuest')questEditor(id);
 else if(a==='deleteQuest')confirmAction('일정 삭제','앞으로의 목록에서 이 일정을 숨길까요? 이미 완료한 기록과 보상은 남아요.',()=>{mutate(()=>{E.deleteQuest(s,id);toast('일정을 삭제했어요.')});close()});
 else if(a==='toggleQuest'){const log=mutate(()=>E.toggleQuest(s,id));if(log){if(log.cancelled)toast('완료를 취소하고 '+fmt(log.amount)+' G를 회수했어요.');else diceModal(log)}}
 else if(a==='reportTab'){reportTab=b.dataset.tab;render()}else if(a==='metric'){metric=b.dataset.metric;render()}else if(a==='range'){range=b.dataset.range;render()}
 else if(a==='stamp'){s.stamps[b.dataset.date]=true;save();render();toast('오늘의 기록에 도장을 찍었어요.')}
 else if(a==='openReceipt'){go('reports');reportTab='receipt';render()}
 else if(a==='manageState'){manageState=b.dataset.state;render()}
 else if(a==='wisdomLibrary')wisdomLibrary();
 else if(a==='place')placement(id);
 else if(a==='placementFloor')placement(id,Number(b.dataset.floor));
 else if(a==='placeConfirm'){E.placeFurniture(s,id,Number(b.dataset.floor),Number(b.dataset.slot));save();render();furniture(id);toast('선택한 공간에 가구를 배치했어요.')}
 else if(a==='store'){E.storeFurniture(s,id);save();render();furniture(id);toast('가구를 보관실에 옮겼어요.')}
 else if(a==='shopFloor'){shopFloor=Number(b.dataset.floor);filter='all';render()}else if(a==='shopSlot'){shopSlot=Number(b.dataset.slot);render()}else if(a==='shopTab'){shopTab=b.dataset.tab;render()}else if(a==='filter'){filter=b.dataset.filter;render()}
 else if(a==='buy'){if(ready()){const item=mutate(()=>E.buy(s,id));if(item){toast('가구를 구매했어요. 배치할 공간을 골라주세요.');furniture(item.uid)}}}
 else if(a==='furniture')furniture(id);else if(a==='upgrade'){const item=mutate(()=>E.upgradeFurniture(s,id));if(item){furniture(id);toast('Lv.'+item.level+' 업그레이드! 새 스킨이 해금됐어요.')}}
 else if(a==='skin'){E.setFurnitureSkin(s,id,Number(b.dataset.skin));save();render();furniture(id);toast('선택한 스킨으로 꾸몄어요.')}
 else if(a==='decorateFloor'){shopFloor=Number(b.dataset.floor);shopTab='manage';filter='all';go('shop')}
 else if(a==='employee')employeeDetail(id);else if(a==='candidate')candidateDetail(id);
 else if(a==='hire'){const c=E.candidates(s).find(c=>c.id===id),f=Number($('#hireFloor').value);E.hire(s,c,f);animationEpoch=performance.now();save();close();render();toast(c.name+' 님이 입사했어요.')}
 else if(a==='move'){const f=Number($('#moveFloor').value);E.moveStaff(s,id,f);animationEpoch=performance.now();save();render();employeeDetail(id);toast('새 부서로 재배치했어요.')}
 else if(a==='fire'){const e=s.staff.find(e=>e.id===id);confirmAction(e.name+' 님 해고','퇴직금 '+E.WAGES[e.star]*3+' G가 지급돼요. 다시 채용하면 처음부터 성장해요.',()=>{mutate(()=>E.fire(s,id));animationEpoch=performance.now();toast('퇴직금을 지급했어요.')})}
 else if(a==='lobby'){$('#screen').scrollTo({top:820*zoom,behavior:'smooth'})}
 else if(a==='roof'){$('#screen').scrollTo({top:125,behavior:'smooth'})}
 else if(a==='meeting')meeting();else if(a==='lounge')lounge();else if(a==='investors')investors();
 else if(a==='addSuggestion'){const q=suggestions[Number(b.dataset.index)];if(s.customQuests.some(x=>!x.deletedOn&&x.title===q.title&&E.scheduledQuests(s,q.type).some(a=>a.id===x.id))){toast('이미 오늘의 일정에 담겨 있어요.');return}E.upsertQuest(s,{...q,repeat:'once',days:[],startDate:s.day});save();render();toast('일정에 제안서를 담았어요. 일정에서 확인하세요.')}
 else if(a==='invest'){const o=E.INVESTORS.find(o=>o.id===id);confirmAction('투자사 계약 확인',o.kind?o.title+' 활동을 했나요? 확인하면 활동을 기록하고 '+o.reward+' G를 받아요.':o.desc,()=>{if(o.kind)E.setActivity(s,o.kind,true);E.acceptInvestor(s,id);save();render();investors();toast('계약을 완료했어요.')})}
 else if(a==='testAdvance'){if(mode!=='demo'){toast('샘플 회사에서만 날짜를 진행할 수 있어요.');return}if(ready()){const r=E.advance(s);selectedDay=null;save();close();render();settled(r)}}
 else if(a==='export')download();else if(a==='import')$('#importFile').click();
 }catch(e){toast(e.message)}});
document.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,f=new FormData(form);try{
 if(form.id==='recordForm'){const r={weight:Number(f.get('weight')),note:f.get('note')};for(const k of ['muscle','fat','sleep','calories'])r[k]=String(f.get(k)||'').trim()===''?null:Number(f.get(k));const delta=E.setRecord(s,f.get('date'),r);save();close();render();toast('기록을 저장했어요.'+(delta?' 배당 차액 '+(delta>0?'+':'')+fmt(delta)+' G 반영.':''))}
 if(form.id==='profileForm'){const p={name:String(f.get('name')).trim(),mode:f.get('mode'),goalDate:f.get('goalDate'),closeTime:f.get('closeTime')};for(const k of ['age','height','start','target','range'])p[k]=Number(f.get(k));if(!p.name)throw Error('회사 이름을 입력해주세요.');if(p.mode==='lose'&&p.target>=p.start)throw Error('감량 목표는 시작 체중보다 낮게 설정해주세요.');const initial=!s.profile;s.profile=p;save();close();render();toast(initial?'새로운 회사를 설립했어요.':'회사 설정을 저장했어요.');if(initial)startup()}
 if(form.id==='renameForm'){const n=String(f.get('name')).trim();if(!n)throw Error('회사 이름을 입력해주세요.');s.profile.name=n;save();close();render();toast('회사 이름을 바꿨어요.')}
 if(form.id==='questForm'){E.upsertQuest(s,{id:form.dataset.id||null,type:form.dataset.type,title:f.get('title'),difficulty:f.get('difficulty'),category:f.get('category'),repeat:f.get('repeat'),days:f.getAll('days').map(Number),startDate:f.get('startDate')});save();close();render();toast('나만의 약속을 저장했어요.')}
 }catch(e){toast(e.message)}});
document.addEventListener('change',async ev=>{const t=ev.target;
 if(t.id==='questDifficulty')$('#rewardPreview').innerHTML=rewardPreview($('#questForm').dataset.type,t.value);
 if(t.id==='questRepeat'&&$('#weekdayBlock'))$('#weekdayBlock').classList.toggle('hide',t.value==='once');
 if(t.id==='receiptDate'){receiptDate=t.value;render()}
 if(t.form?.id==='recordForm'&&t.name==='date'){const d=t.value;if(/^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=s.day)recordForm(d)}
 if(t.id==='importFile'&&t.files[0]){try{if(t.files[0].size>8e6)throw Error('백업 파일이 너무 커요.');const data=validate(JSON.parse(await t.files[0].text()));confirmAction('백업 가져오기','현재 '+(mode==='demo'?'샘플 회사':'내 회사')+' 기록을 이 백업으로 바꿀까요? 필요하면 먼저 백업을 내려받아주세요.',()=>{s=data;save();close();render();toast('백업을 가져왔어요.');startup()})}catch(e){toast(e.message)}}
});
$('#sheet').addEventListener('click',ev=>{if(ev.target===$('#sheet')){const r=$('#sheet').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)close()}});
$('#sheet').addEventListener('cancel',()=>pending=null);
if(mode==='real')E.catchUp(s);save();render();startup();
setInterval(()=>{if(mode==='real'&&E.catchUp(s)){selectedDay=null;save();render();startup()}},60000);

window.addEventListener('saebomresume',()=>{if($('#sheet').open)return;if(mode==='real'){E.catchUp(s);save();render();startup()}});
